CREATE TABLE customers (id bigint unsigned AUTO_INCREMENT PRIMARY KEY,email varchar(255) UNIQUE NOT NULL,display_name varchar(255) NOT NULL,country_code char(2) NOT NULL,preferences json NOT NULL,archived_at datetime NULL) CHARACTER SET utf8mb4;
CREATE TABLE products (id bigint unsigned AUTO_INCREMENT PRIMARY KEY,sku varchar(50) UNIQUE NOT NULL,name varchar(255) NOT NULL,unit_price decimal(10,2) NOT NULL,metadata json NOT NULL) CHARACTER SET utf8mb4;
CREATE TABLE orders (id bigint unsigned AUTO_INCREMENT PRIMARY KEY,customer_id bigint unsigned NOT NULL,status enum('pending','paid','shipped','refunded') NOT NULL,ordered_at datetime NOT NULL,notes text NULL,FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE order_items(order_id bigint unsigned NOT NULL,product_id bigint unsigned NOT NULL,quantity int NOT NULL,unit_price decimal(10,2) NOT NULL,PRIMARY KEY(order_id,product_id),FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(product_id) REFERENCES products(id));
INSERT INTO customers(email,display_name,country_code,preferences,archived_at) SELECT CONCAT('customer.',seq,'@example.test'),CONCAT(ELT(1+seq%5,'Zoë Müller','José García','Sakura 山田','Léa Martin','Alex Smith'),' ',seq),ELT(1+seq%5,'DE','ES','JP','FR','GB'),JSON_OBJECT('newsletter',seq%3=0,'loyalty_points',seq*7),IF(seq%17=0,'2026-10-01 12:00:00',NULL) FROM seq_1_to_120;
INSERT INTO products(sku,name,unit_price,metadata) SELECT CONCAT('SKU-',LPAD(seq,4,'0')),CONCAT(ELT(1+seq%5,'Notebook','Desk lamp','Travel mug','Keyboard','USB cable'),' ',seq),5.5+seq*2.75,JSON_OBJECT('stock',seq*7,'supplier',CONCAT('supplier-',1+seq%4)) FROM seq_1_to_30;
INSERT INTO orders(customer_id,status,ordered_at,notes) SELECT 1+(seq-1)%120,ELT(1+seq%4,'pending','paid','shipped','refunded'),DATE_ADD('2026-01-01 10:00:00',INTERVAL seq*12 HOUR),IF(seq%9=0,'Gift wrap; handle with care',NULL) FROM seq_1_to_360;
INSERT INTO order_items SELECT o.id,p.id,1+(o.id+s.seq)%4,p.unit_price FROM orders o CROSS JOIN seq_0_to_2 s JOIN products p ON p.id=1+(o.id+s.seq)%30;
CREATE VIEW order_summary AS SELECT o.id,o.customer_id,c.display_name,o.status,o.ordered_at,count(*) AS line_count,sum(i.quantity*i.unit_price) AS total FROM orders o JOIN customers c ON c.id=o.customer_id JOIN order_items i ON i.order_id=o.id GROUP BY o.id,o.customer_id,c.display_name,o.status,o.ordered_at;
SELECT 'customers' AS fixture,count(*) FROM customers UNION ALL SELECT 'products',count(*) FROM products UNION ALL SELECT 'orders',count(*) FROM orders UNION ALL SELECT 'order_items',count(*) FROM order_items;
